document.getElementById('year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.publication').forEach(p=>{p.hidden=button.dataset.filter!=='all'&&p.dataset.kind!==button.dataset.filter})}));
const newsButton=document.getElementById('more-news');newsButton.addEventListener('click',()=>{const expand=newsButton.getAttribute('aria-expanded')!=='true';document.querySelectorAll('.older-news').forEach(n=>n.hidden=!expand);newsButton.setAttribute('aria-expanded',String(expand));newsButton.textContent=expand?'Show fewer updates −':'Show earlier updates +'});
